const msg = $input.first().json.message.text;
const chatId = String($input.first().json.message.chat.id);
const partes = msg.replace(/^\/agendar\s*/i, '').split('|').map(p => p.trim());
const titulo = partes[0] || 'Sin título';
const fechaHora = partes[1] || '';
const descripcion = partes[2] || '';

function parseFecha(texto) {
  const dias = { lunes: 1, martes: 2, miercoles: 3, miércoles: 3, jueves: 4, viernes: 5, sabado: 6, sábado: 6, domingo: 0 };
  const lower = texto.toLowerCase();
  const fecha = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/La_Paz' }));
  if (lower.includes('mañana') || lower.includes('manana')) {
    fecha.setDate(fecha.getDate() + 1);
  } else {
    for (const [nombre, num] of Object.entries(dias)) {
      if (lower.includes(nombre)) {
        const hoy = fecha.getDay();
        let diff = num - hoy;
        if (diff <= 0) diff += 7;
        fecha.setDate(fecha.getDate() + diff);
        break;
      }
    }
    const matchSlash = texto.match(/(\d{1,2})\/(\d{1,2})/);
    if (matchSlash) { fecha.setMonth(parseInt(matchSlash[2]) - 1); fecha.setDate(parseInt(matchSlash[1])); }
  }
  return fecha;
}

function parseHora(texto) {
  const match = texto.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
  if (!match) return { h: 9, m: 0 };
  let h = parseInt(match[1]);
  const m = parseInt(match[2] || '0');
  const ampm = (match[3] || '').toLowerCase();
  if (ampm === 'pm' && h < 12) h += 12;
  if (ampm === 'am' && h === 12) h = 0;
  return { h, m };
}

const fecha = parseFecha(fechaHora);
const rangoMatch = fechaHora.match(/([\d:apm]+)\s*-\s*([\d:apm]+)/i);
let startH = { h: 9, m: 0 }, endH = { h: 10, m: 0 };
if (rangoMatch) { startH = parseHora(rangoMatch[1]); endH = parseHora(rangoMatch[2]); }

const startDate = new Date(fecha);
startDate.setHours(startH.h, startH.m, 0, 0);
const endDate = new Date(fecha);
endDate.setHours(endH.h, endH.m, 0, 0);

const resumen = titulo + ' — ' + startDate.toLocaleString('es-BO', { timeZone: 'America/La_Paz', weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
return [{ json: { titulo, descripcion, startISO: startDate.toISOString(), endISO: endDate.toISOString(), chatId, resumen } }];
